SELECT data.commit.collection AS event, TO_STRING(data.did) AS d, COUNT(*) AS cnt, COUNT(DISTINCT d) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5;
SELECT data.commit.collection AS event, COUNT(*) AS cnt, COUNT(DISTINCT TO_STRING(data.did)) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5;
SELECT data.commit.collection AS event, data.did AS d, COUNT(*) AS cnt, COUNT(DISTINCT d) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5;
SELECT data.commit.collection AS event, TO_STRING(data.did) AS d, COUNT(*) AS cnt, COUNT(DISTINCT d) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5 OPTION distinct_precision_threshold=0;
SELECT data.commit.collection AS event, TO_STRING(data.did) AS d, COUNT(*) AS cnt, COUNT(DISTINCT d) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5 OPTION distinct_precision_threshold=10000000;
SELECT data.commit.collection AS event, COUNT(*) AS cnt, COUNT(DISTINCT CRC32(data.did)) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5;
SELECT data.commit.collection AS event, CRC32(data.did) AS h, COUNT(*) AS cnt, COUNT(DISTINCT h) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5 OPTION distinct_precision_threshold=0;
SELECT COUNT(DISTINCT data.did) FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post';
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS a, MAX(BIGINT(data.time_us)) AS b FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY b - a DESC LIMIT 3;
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS a, MAX(BIGINT(data.time_us)) AS b FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY MAX(BIGINT(data.time_us)) DESC LIMIT 3;
SELECT data.did AS user_id, MAX(BIGINT(data.time_us)) + (0 - MIN(BIGINT(data.time_us))) AS s FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY s DESC LIMIT 3;
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS first_post_ts FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT data.commit.collection AS event, COUNT(*) AS cnt FROM bluesky GROUP BY event ORDER BY cnt DESC LIMIT 10000 OPTION max_matches=10000;
